create table citizen (
	village_id INT,
	citizen_id INT,
	password_hash VARCHAR(255) not null,
	aadhar VARCHAR(50) PRIMARY KEY,
	gender VARCHAR(50),
	name VARCHAR(6),
	email VARCHAR(50),
	image VARCHAR(157),
	household_id INT REFERENCES household(household_id),
	dob DATE,
	education_qualification VARCHAR(50)
);




